#!/usr/bin/env bash
# Stamps a release version into the build: writes internal/app/version/zz_release.go,
# which sets version.Version and version.Commit when the program starts.
#
#   scripts/stamp-version.sh <tag> [commit]      e.g. scripts/stamp-version.sh v0.2.0 "$GITHUB_SHA"
#
# The release workflow runs it before every build. A generated file is used
# instead of -ldflags -X because `fyne package` drops -ldflags from GOFLAGS
# when it rebuilds the Windows exe with its icon and version info. The file is
# git-ignored; delete it to go back to a "dev" build.
set -euo pipefail

cd "$(dirname "$0")/.."
tag="${1:?usage: stamp-version.sh <tag> [commit]}"
commit="${2:-$(git rev-parse HEAD 2>/dev/null || true)}"

case "$tag$commit" in
  *[!A-Za-z0-9._+-]*) echo "unexpected characters in tag or commit: $tag $commit" >&2; exit 1 ;;
esac

out=internal/app/version/zz_release.go
cat > "$out" <<EOF
// Code generated by scripts/stamp-version.sh. DO NOT EDIT.

package version

func init() {
	Version = "$tag"
	Commit = "$commit"
}
EOF
echo "wrote $out ($tag, ${commit:0:7})"
